@@ -96,6 +96,21 @@ function getLastEntryInMultiHeaderValue (headerValue) {
   return lastIndex === -1 ? headerValue.trim() : headerValue.slice(lastIndex + 1).trim()
 }

+// The `x-forwarded-*` headers are only meaningful when the peer that sent them
+// is a proxy we trust: any client can set them. `ip` and `ips` are already
+// gated because `proxyAddr` truncates the chain at the first untrusted hop, so
+// `host` and `protocol` have to ask the trust function about the peer itself.
+function isTrustedProxy (request, proxyFn) {
+  // `getTrustProxyFn` returns `null` for `trustProxy: true`, which trusts every
+  // proxy and therefore needs no check.
