test('trust proxy - untrusted peer cannot spoof host and protocol', async t => {
  t.plan(4)
  const app = fastify({
    // the loopback address the request comes from is deliberately not trusted
    trustProxy: '2.2.2.2'
  })
  t.after(() => app.close())

  app.get('/untrusted', function (req, reply) {
    t.assert.strictEqual(req.host, `${localhost}:${app.server.address().port}`, 'x-forwarded-host is ignored')
    t.assert.strictEqual(req.hostname, localhost, 'hostname is derived from the host header')
    t.assert.strictEqual(req.port, app.server.address().port, 'port is derived from the host header')
    t.assert.strictEqual(req.protocol, 'http', 'x-forwarded-proto is ignored')
    reply.code(200).send({ host: req.host, protocol: req.protocol })
  })

  const fastifyServer = await app.listen({ port: 0 })
  await fetchForwardedRequest(fastifyServer, '1.1.1.1', '/untrusted', 'https')
})
EOF
